-- SQL baseline (applied to production 2026-10-03, PostgreSQL 18; compatible with 16).
-- Changes go through a reviewed PR; Phase B moves this into Drizzle migrations.
-- ids are generated by the application (no DB defaults).
-- "expired" is never stored: it is computed as status = 'pending' AND expires_at <= now().
-- Invitations last 7 days (OD-3). Resend keeps the same row, sets a new expires_at and a new token_hash (old link stops working).
-- User limit = active memberships + pending, non-expired invitations.

CREATE TABLE invitations (
  clinic_id          uuid NOT NULL REFERENCES clinics (id),
  id                 uuid NOT NULL,
  email              text NOT NULL,
  full_name          text NOT NULL,
  role_id            uuid NOT NULL,
  all_branches       boolean NOT NULL,
  status             text NOT NULL CHECK (status IN ('pending','accepted','cancelled')),
  expires_at         timestamptz NOT NULL,
  invited_by_user_id uuid NOT NULL,
  token_hash         text NOT NULL,
  created_at         timestamptz NOT NULL,
  responded_at       timestamptz NULL,
  PRIMARY KEY (clinic_id, id),
  FOREIGN KEY (clinic_id, role_id) REFERENCES roles (clinic_id, id)
);
CREATE INDEX invitations_clinic_status_idx ON invitations (clinic_id, status, expires_at);
CREATE INDEX invitations_clinic_email_idx ON invitations (clinic_id, lower(email));

ALTER TABLE invitations ENABLE ROW LEVEL SECURITY;
ALTER TABLE invitations FORCE ROW LEVEL SECURITY;
CREATE POLICY invitations_tenant_isolation ON invitations
  USING (clinic_id = current_setting('app.clinic_id')::uuid)
  WITH CHECK (clinic_id = current_setting('app.clinic_id')::uuid);

-- Branches offered by an invitation when all_branches = false (copied to membership_branches on accept).
CREATE TABLE invitation_branches (
  clinic_id     uuid NOT NULL,
  id            uuid NOT NULL,
  invitation_id uuid NOT NULL,
  branch_id     uuid NOT NULL,
  PRIMARY KEY (clinic_id, id),
  UNIQUE (clinic_id, invitation_id, branch_id),
  FOREIGN KEY (clinic_id, invitation_id) REFERENCES invitations (clinic_id, id),
  FOREIGN KEY (clinic_id, branch_id) REFERENCES branches (clinic_id, id)
);
CREATE INDEX invitation_branches_clinic_branch_idx ON invitation_branches (clinic_id, branch_id);

ALTER TABLE invitation_branches ENABLE ROW LEVEL SECURITY;
ALTER TABLE invitation_branches FORCE ROW LEVEL SECURITY;
CREATE POLICY invitation_branches_tenant_isolation ON invitation_branches
  USING (clinic_id = current_setting('app.clinic_id')::uuid)
  WITH CHECK (clinic_id = current_setting('app.clinic_id')::uuid);
